import math

# Set alpha = sqrt(2) for initial testing
alpha = math.sqrt(2)

def E(m, n, alpha):
    # E(m, n) = m*ceil(n*alpha) - n*floor(m*alpha)
    # Use math.ceil and math.floor which handle floats
    try:
        term1 = m * math.ceil(n * alpha)
        term2 = n * math.floor(m * alpha)
        return int(term1 - term2)
    except OverflowError:
        return None

# Test small pairs (m, n)
test_pairs = [
    (1, 1), (2, 1), (1, 2), (3, 1), (1, 3), (2, 2), (4, 1), (1, 4),
    (3, 2), (2, 3), (4, 3), (3, 4)
]

results = {}
for m, n in test_pairs:
    k_val = E(m, n, alpha)
    gcd = math.gcd(m, n)
    results[(m, n)] = {'k': k_val, 'gcd': gcd}

print("--- Testing E(m, n) for alpha = sqrt(2) ---")
for pair, data in results.items():
    print(f"Pair ({pair[0]}, {pair[1]}), GCD={data['gcd']}, k={data['k']}")

